{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_ef8452d023dbd2c94de13706", "claim_ids": ["claim_4bd3cb5ba8b4c1173e650aac", "claim_cc7ab815924e59e6a91119b9"], "query_ids": ["q_429"], "claims": [{"claim_id": "claim_4bd3cb5ba8b4c1173e650aac", "quote": "The only NdFeB magnet production that occurs in the United States is performed on a small scale that does not match demand.", "url": "https://www.energy.gov/sites/default/files/2022-02/Neodymium%20Magnets%20Supply%20Chain%20Report%20-%20Final.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States"}}, {"claim_id": "claim_cc7ab815924e59e6a91119b9", "quote": "The lone domestic producer, Urban Mining Company, manufactures sintered NdFeB magnets from recycled material and has received funding from the DPA Title III program.", "url": "https://www.energy.gov/sites/default/files/2022-02/Neodymium%20Magnets%20Supply%20Chain%20Report%20-%20Final.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Urban Mining Company"}}]}, {"pair_id": "conflict_38b23d1c1e953ba535424274", "claim_ids": ["claim_5a4314ea1a227b996d645f84", "claim_ec3fd2786505c5538edd72c2"], "query_ids": ["q_429"], "claims": [{"claim_id": "claim_5a4314ea1a227b996d645f84", "quote": "Rare earth materials sourced from Mountain Pass, California, will be manufactured into magnets at new MP Materials production facility in Fort Worth, Texas", "url": "https://mpmaterials.com/news//general-motors-and-mp-materials-enter-long-term-supply-agreement-to-scale-rare-earth-magnet-sourcing-and-production-in-the-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "MP Materials", "facility": "Fort Worth, Texas"}}, {"claim_id": "claim_ec3fd2786505c5538edd72c2", "quote": "MP Materials owns and operates the Mountain Pass rare earth mine and processing facility in California, the only active and scaled rare earth production site in America.", "url": "https://mpmaterials.com/news//general-motors-and-mp-materials-enter-long-term-supply-agreement-to-scale-rare-earth-magnet-sourcing-and-production-in-the-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "MP Materials", "facility": "Mountain Pass rare earth mine and processing facility"}}]}, {"pair_id": "conflict_2fbbc8f486c1f0f847f76182", "claim_ids": ["claim_112c0012a45f09c64276d8d8", "claim_5aac0550c35c5686085fc716"], "query_ids": ["q_430"], "claims": [{"claim_id": "claim_112c0012a45f09c64276d8d8", "quote": "Certain qualifying two-layer and four-layer rigid PCBs may use Section 301 exclusion code 9903.88.69 through November 9, 2026.", "url": "https://www.ourpcb.com/blog/china-us-pcb-tariffs-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"chapter_99_code": "9903.88.69", "expiration_date": "November 9, 2026"}}, {"claim_id": "claim_5aac0550c35c5686085fc716", "quote": "Based on current industry classifications and customs data, all HTS codes we have observed for semiconductors, PCBs, and PCB assemblies sourced from China are subject to the Section 301 tariffs. This includes HTS codes in Chapters 85 and 90 most relevant to electronic components: - 8541.x / 8542.x: Semiconductors (now at 50%) - 8534.00.0020 / 0040: Two- and four-layer rigid PCBs excluded until May 31, 2025 - 8534.00.00: Other bare PCBs—25% duty", "url": "https://www.cofactr.com/articles/definitive-guide-to-semiconductor-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Other bare PCBs", "hts_code": "8534.00.00", "duty_rate": "25%"}}]}, {"pair_id": "conflict_cb33b344262d0da966e69cc4", "claim_ids": ["claim_15ba285ff1e8d11f6f93efab", "claim_d59ef5e6d74c4de71fd8ded6"], "query_ids": ["q_430"], "claims": [{"claim_id": "claim_15ba285ff1e8d11f6f93efab", "quote": "For many China-origin PCB imports, the normal base duty may be Free, but Section 301 can add 25% unless a valid exclusion applies.", "url": "https://www.ourpcb.com/blog/china-us-pcb-tariffs-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%"}}, {"claim_id": "claim_d59ef5e6d74c4de71fd8ded6", "quote": "For many China-origin bare PCBs under HTS 8534.00 and certain PCBAs under HTS 8473.30.1180, the additional Section 301 tariff is 25% unless a product-specific exclusion applies.", "url": "https://www.ourpcb.com/blog/china-us-pcb-tariffs-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "China", "duty_rate": "25%"}}]}, {"pair_id": "conflict_9c3a8eb4ad833c1c462eab48", "claim_ids": ["claim_6895fc2376c9a257563df81d", "claim_fa2cb28377375f538de6e663"], "query_ids": ["q_432"], "claims": [{"claim_id": "claim_6895fc2376c9a257563df81d", "quote": "In April 2025, the United States has implemented new tariffs on Chinese imports, including printed circuit boards (PCBs) and custom-made technical parts.", "url": "https://www.icape-group.com/pcb-tariff-information", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ICAPE Group", "tariff_program": "new tariffs on Chinese imports", "affected_product": "printed circuit boards (PCBs) and custom-made technical parts", "effective_date": "April 2025"}}, {"claim_id": "claim_fa2cb28377375f538de6e663", "quote": "| China | 30% DS/4Layer, 55% other | 14/05/25 | Until 12/11/25 | Interim deal; 90-day truce. |", "url": "https://www.icape-group.com/pcb-tariff-information", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "30% DS/4Layer, 55% other", "effective_date": "14/05/25", "expiration_date": "Until 12/11/25", "reported_policy_status": "Interim deal; 90-day truce"}}]}, {"pair_id": "conflict_3189b463ac6668eb3ad36b1b", "claim_ids": ["claim_631ab6751f89ff1743c64b3a", "claim_6f5e1b376a964af2a6f8d320"], "query_ids": ["q_435"], "claims": [{"claim_id": "claim_631ab6751f89ff1743c64b3a", "quote": "Solar inverters (string inverters, microinverters, and hybrid/multi-mode inverters) are classified under 8504.40 as static converters.", "url": "https://dutiable.io/hs-code/solar-renewable-energy/solar-inverter", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8504.40"}}, {"claim_id": "claim_6f5e1b376a964af2a6f8d320", "quote": "The HS code for solar inverters & grid-tie inverters is 8504.40.55. Import duty rates: EU 0%, US Free, UK 0%. Rates verified April 2026 against USITC HTS.", "url": "https://dutiable.io/hs-code/solar-renewable-energy/solar-inverter", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "US Free", "hts_code": "8504.40.55", "effective_date": "April 2026"}}]}, {"pair_id": "conflict_e593c7e8e0ae7b76598abbe4", "claim_ids": ["claim_28da344f68d21a7c110d1942", "claim_28e921f07cd1615b9cd37365"], "query_ids": ["q_435"], "claims": [{"claim_id": "claim_28da344f68d21a7c110d1942", "quote": "Enphase and SolarEdge (manufacturing in Hungary) have signaled stable pricing for U.S. customers, using non-Chinese factories to dodge the steepest duties.", "url": "https://www.sunhub.com/blog/april-2025-reciprocal-tariffs-solar-equipment", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "SolarEdge", "country_of_origin": "Hungary"}}, {"claim_id": "claim_28e921f07cd1615b9cd37365", "quote": "Under the new policy, all imports face at least 10% tariff, and specific countries face more – China-made inverters now see ~34% tariff, European inverters ~20%, South Korea 25%, etc.", "url": "https://www.sunhub.com/blog/april-2025-reciprocal-tariffs-solar-equipment", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new policy", "country_of_origin": "China", "duty_rate": "~34%"}}]}, {"pair_id": "conflict_ab646cd2f18a7b4133e9eebd", "claim_ids": ["claim_28e921f07cd1615b9cd37365", "claim_9159253885562047d5d7afb6"], "query_ids": ["q_435"], "claims": [{"claim_id": "claim_28e921f07cd1615b9cd37365", "quote": "Under the new policy, all imports face at least 10% tariff, and specific countries face more – China-made inverters now see ~34% tariff, European inverters ~20%, South Korea 25%, etc.", "url": "https://www.sunhub.com/blog/april-2025-reciprocal-tariffs-solar-equipment", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new policy", "country_of_origin": "China", "duty_rate": "~34%"}}, {"claim_id": "claim_9159253885562047d5d7afb6", "quote": "Solar inverters have also seen price pressures from the tariff updates, though the impact varies by manufacturer origin. Many popular inverter brands for U.S. solar projects are made in China or other foreign countries (for example: Growatt, Sungrow, Solis from China; SolarEdge from Israel/Hungary; SMA from Germany; Fronius from Austria; Huawei (utility-scale) from China, etc.). Under the new policy, all imports face at least 10% tariff, and specific countries face more – China-made inverters now see ~34% tariff, European inverters ~20%, South Korea 25%, etc.", "url": "https://www.sunhub.com/blog/april-2025-reciprocal-tariffs-solar-equipment", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "~34%"}}]}, {"pair_id": "conflict_336643260a31c874d8b445dc", "claim_ids": ["claim_0b67f93d87d4b6f60c0d0404", "claim_ebd1c3744115a7eccb4a6fd7"], "query_ids": ["q_435"], "claims": [{"claim_id": "claim_0b67f93d87d4b6f60c0d0404", "quote": "Inverters from China (Growatt, Sungrow) likewise rose ~30–34%.", "url": "https://www.sunhub.com/blog/april-2025-reciprocal-tariffs-solar-equipment", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Sungrow", "duty_rate": "~30–34%"}}, {"claim_id": "claim_ebd1c3744115a7eccb4a6fd7", "quote": "Inverters from China (Growatt, Sungrow) likewise rose ~30–34%.", "url": "https://www.sunhub.com/blog/april-2025-reciprocal-tariffs-solar-equipment", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Growatt", "duty_rate": "~30–34%"}}]}, {"pair_id": "conflict_8823f858486169339a81099d", "claim_ids": ["claim_50342eb6da344909e00484bb", "claim_d56bcc70dbacd6091bb184dc"], "query_ids": ["q_438"], "claims": [{"claim_id": "claim_50342eb6da344909e00484bb", "quote": "8501324500—ELEC MTRS, SOURCE OF MECH POWER FOR VEH 8703.40-80", "url": "https://www.trade.gov/automotive-parts-tariff-codes", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "ELEC MTRS, SOURCE OF MECH POWER FOR VEH 8703.40-80", "hts_code": "8501324500"}}, {"claim_id": "claim_d56bcc70dbacd6091bb184dc", "quote": "Electric control boards of the following characteristics would be traditionally classified under HTSUS heading 8537: (1) Comprising at least two components under HTSUS heading 8535 or 8536; (2) Incorporating programmable memory for the storage of instructions; and (3) Electrically controlling various functions of another device.", "url": "https://www.jdsupra.com/legalnews/re-thinking-strategies-for-7978507", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}]}

